<x-layouts.app><a href="{{ route(session('svrms_role').'.dashboard') }}" class="text-sm font-bold text-red-700">&larr; Dashboard</a><div class="mt-4 max-w-3xl"><p class="text-sm font-bold tracking-widest text-red-700">INCIDENT INTAKE</p><h1 class="text-3xl font-black">Record a violation</h1><p class="mt-1 text-zinc-600">Report incidents directly observed by the guard. Classroom and academic violations are excluded. Major and custom reports require administrator review.</p><form data-incident-form method="POST" action="{{ route(session('svrms_role').'.reports.store') }}" class="mt-7 space-y-6 rounded-xl bg-white p-6 shadow-sm">@csrf <input type="hidden" name="submission_token" value="{{ old('submission_token', $submissionToken) }}"> @if(session('svrms_role') === 'admin')<label class="block font-bold">Reporting Guard<select required name="guard_id" class="mt-1 w-full"><option value="">Select reporting guard</option>@foreach($guards as $guard)<option value="{{ $guard->guard_id }}" @selected(old('guard_id') == $guard->guard_id)>{{ $guard->name }}</option>@endforeach</select></label>@endif<label class="block font-bold">Student SR-Code<input id="sr-code" required name="sr_code" value="{{ old('sr_code') }}" class="mt-1 w-full rounded border-zinc-300" placeholder="e.g. 21-00000"></label><div id="student-result" class="hidden rounded border border-zinc-200 bg-zinc-50 p-4 text-sm"></div><label class="block font-bold">Violation<select required id="violation-select" name="violation_id" class="mt-1 w-full rounded border-zinc-300"><option value="">Select a guard-reportable violation</option>@foreach($violations as $v)<option value="{{ $v->violation_id }}" @selected(old('violation_id') == $v->violation_id)>{{ $v->violation_name }} &mdash; {{ $v->violation_weight }}</option>@endforeach<option value="other" @selected(old('violation_id') === 'other')>Other — please specify</option></select></label><div id="other-violation-field" @if(old('violation_id') !== 'other') hidden @endif><label class="block font-bold">Specify the violation<input name="other_violation" value="{{ old('other_violation') }}" maxlength="255" class="mt-1 w-full" placeholder="Enter the violation name" @required(old('violation_id') === 'other')></label><p class="mt-2 text-sm text-zinc-500">Custom violations are submitted for administrator review before confirmation.</p></div><div class="grid gap-6 sm:grid-cols-2"><label class="block font-bold">Incident date & time<input required name="incident_at" type="datetime-local" max="{{ now()->timezone('Asia/Singapore')->format('Y-m-d') }}T23:59" value="{{ old('incident_at') }}" class="mt-1 w-full rounded border-zinc-300"></label><label class="block font-bold">Location<input required name="location" class="mt-1 w-full rounded border-zinc-300"></label></div><label class="block font-bold">Factual incident statement<textarea required name="incident_statement" rows="5" class="mt-1 w-full rounded border-zinc-300" placeholder="State observable facts only."></textarea></label><button class="rounded bg-red-700 px-5 py-3 font-bold text-white">Submit report for processing</button></form></div><script nonce="{{ \Illuminate\Support\Facades\Vite::cspNonce() }}">const input=document.querySelector('#sr-code'),result=document.querySelector('#student-result');input.addEventListener('change',async()=>{if(!input.value)return;let r=await fetch(@json(route(session('svrms_role').'.students.lookup', '__CODE__')).replace('__CODE__',encodeURIComponent(input.value)));let d=await r.json();result.classList.remove('hidden');result.textContent=r.ok?`${d.student_name} / ${d.sr_code} / ${d.program}, ${d.department_name}${d.year_level?' / Year '+d.year_level:''}`:d.message;result.className=`rounded border p-4 text-sm ${r.ok?'border-green-200 bg-green-50 text-green-900':'border-red-200 bg-red-50 text-red-900'}`})</script></x-layouts.app>
